package shipping;

/**
 * Selects which version of the program the tests run against, using the system
 * property "target":  ref (default), f01 ... f10.
 *
 * <p>Your tests must always call {@code Target.fee(...)}, never the program classes
 * directly. Do not edit this file.
 */
public final class Target {

    private Target() {
    }

    public static int fee(int weight, int distance, boolean express, boolean member) {
        String target = System.getProperty("target", "ref");
        switch (target) {
            case "ref": return ShippingRef.fee(weight, distance, express, member);
            case "f01": return ShippingF01.fee(weight, distance, express, member);
            case "f02": return ShippingF02.fee(weight, distance, express, member);
            case "f03": return ShippingF03.fee(weight, distance, express, member);
            case "f04": return ShippingF04.fee(weight, distance, express, member);
            case "f05": return ShippingF05.fee(weight, distance, express, member);
            case "f06": return ShippingF06.fee(weight, distance, express, member);
            case "f07": return ShippingF07.fee(weight, distance, express, member);
            case "f08": return ShippingF08.fee(weight, distance, express, member);
            case "f09": return ShippingF09.fee(weight, distance, express, member);
            case "f10": return ShippingF10.fee(weight, distance, express, member);
            default: throw new IllegalArgumentException("unknown target: " + target);
        }
    }
}
